// Struktura: uvod → teorija NER → arhitekture → prethodni rezultati → naš dataset → metodologija → rezultati → diskusija
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType,
  Table, TableRow, TableCell, WidthType, ShadingType, PageBreak,
  TableOfContents, PageNumber, Footer, ImageRun,
} = require('docx');
const fs = require('fs');
const FONT = 'Times New Roman';

const H1 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 260, after: 120 }, children: [new TextRun({ text: t, bold: true })] });
const H2 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 180, after: 100 }, children: [new TextRun({ text: t, bold: true })] });
const H3 = (t) => new Paragraph({ heading: HeadingLevel.HEADING_3, spacing: { before: 140, after: 70 }, children: [new TextRun({ text: t, bold: true, italics: true })] });
const P = (t) => new Paragraph({ alignment: AlignmentType.JUSTIFIED, spacing: { after: 120, line: 360 }, children: [new TextRun({ text: t })] });
const CENTER = (t, o = {}) => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 100 }, children: [new TextRun({ text: t, ...o })] });
const CAP = (t) => new Paragraph({ spacing: { before: 120, after: 60 }, children: [new TextRun({ text: t, bold: true })] });
const MONO = (t) => {
  const lines = String(t).split('\n');
  const runs = [];
  lines.forEach((ln, i) => runs.push(new TextRun({ text: ln, font: 'Courier New', size: 18, break: i > 0 ? 1 : 0 })));
  return new Paragraph({ spacing: { before: 40, after: 120 }, indent: { left: 300 }, children: runs });
};
const tc = (text, { bold = false, w = 1500, shade = null, align = AlignmentType.LEFT } = {}) => new TableCell({
  width: { size: w, type: WidthType.DXA }, shading: shade ? { type: ShadingType.CLEAR, fill: shade } : undefined,
  margins: { top: 40, bottom: 40, left: 80, right: 80 },
  children: [new Paragraph({ alignment: align, children: [new TextRun({ text, bold })] })],
});
const table = (widths, headers, rows) => {
  const head = new TableRow({ tableHeader: true, children: headers.map((h, i) => tc(h, { bold: true, w: widths[i], shade: 'D9D9D9', align: i === 0 ? AlignmentType.LEFT : AlignmentType.CENTER })) });
  const body = rows.map((r) => new TableRow({ children: r.map((cc, i) => tc(cc, { w: widths[i], align: i === 0 ? AlignmentType.LEFT : AlignmentType.CENTER })) }));
  return new Table({ columnWidths: widths, width: { size: widths.reduce((a, b) => a + b, 0), type: WidthType.DXA }, rows: [head, ...body] });
};
let FIGNO = 0;
const IMG = (path, w, h, desc) => { FIGNO++; return [
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120, after: 40 }, children: [new ImageRun({ type: 'png', data: fs.readFileSync(path), transformation: { width: w, height: h } })] }),
  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 160 }, children: [new TextRun({ text: `Слика ${FIGNO}. ${desc}`, italics: true, size: 20 })] }),
];};
const SP = () => new Paragraph({ spacing: { after: 120 }, children: [] });
