// ===== 1. УВОД =====
c.push(H1('1. Увод'));
c.push(P('Дигитализација текстуалних садржаја поставила је обраду природног језика (енгл. Natural Language Processing, NLP) у средиште савремених информационих система. Међу темељним задацима ове области издваја се препознавање именованих ентитета — аутоматско проналажење и класификовање речи или група речи које означавају конкретне појмове стварног света, попут имена особа, локација, организација, датума и других [21]. Појам „именовани ентитет" уведен је још деведесетих година, у оквиру конференција посвећених разумевању текста, управо да означи изразе који једнозначно именују неки ентитет [19]. Иако ретко представља крајњи производ, NER је незаобилазна компонента сложенијих система за претрагу, екстракцију информација, повезивање ентитета и аутоматску обраду докумената [15].'));
c.push(P('Домен правних докумената посебно је занимљив због велике количине података која се свакодневно генерише и широког круга корисника — правника, државних органа и грађана [6]. Аутоматизација архивирања, претраге и проналажења правних аката може имати значајан практичан утицај. Ипак, српски језик спада у ниско-ресурсне језике, са ограниченим бројем анотираних корпуса и наменских модела, што отежава развој поузданих решења [4, 5].'));
c.push(P('Последњих година велики језички модели (енгл. Large Language Models, LLM) донели су нов приступ: уместо тренирања засебног модела за сваки задатак, један општи модел наводи се на жељено понашање инструкцијом у тексту (промптовањем) [9, 30]. Остаје отворено питање колико су такви модели, примењени без додатног тренирања, употребљиви за прецизне задатке попут NER-а, нарочито у специјализованом домену и за ниско-ресурсни језик.'));
c.push(P('Циљ овог рада јесте да се испита применљивост промптовања великих језичких модела за препознавање именованих ентитета у српској легислативи, без фино подешавања, и да се одговори на три питања: (1) како се генеративни модели понашају у односу на специјализовани фино подешен модел; (2) какав је утицај врсте модела — инструкцијске наспрам „мислеће" варијанте; и (3) какав је утицај величине модела. Рад је организован тако да се најпре теоријски обради проблем NER-а (поглавље 2), затим архитектуре модела које се за њега користе (поглавље 3), потом досадашњи резултати (поглавље 4), а затим наш пример и структура скупа података (поглавље 5) и методологија експеримента (поглавље 6). Поглавље 7 износи резултате, поглавље 8 дискусију, поглавље 9 ограничења, а поглавље 10 закључак.'));

// ===== 2. ТЕОРИЈСКИ ПРОБЛЕМ NER =====
c.push(H1('2. Теоријски проблем препознавања именованих ентитета'));
c.push(H2('2.1. Дефиниција и формулација задатка'));
c.push(P('Препознавање именованих ентитета формално се дефинише као задатак означавања низа токена: за улазну секвенцу речи модел свакој речи додељује ознаку која указује да ли она припада неком ентитету и ком типу [21, 15]. Задатак обухвата два потпроблема која се решавају истовремено — детекцију граница ентитета (које речи чине ентитет) и класификацију типа ентитета (особа, локација, организација и слично) [15]. Тиме се NER разликује од просте класификације текста, јер излаз није једна ознака по документу, већ структуиран низ ознака по токену [21].'));
c.push(P('У ширем контексту, NER је основни корак у ланцу екстракције информација: тек када су ентитети препознати, могуће је утврдити односе међу њима, повезати их са базама знања и одговарати на упите над текстом [15]. Управо зато квалитет NER-а директно ограничава квалитет свих система који се на њега ослањају.'));
c.push(P('Појам именованог ентитета настао је деведесетих година прошлог века, у оквиру конференција за разумевање текста (MUC), где је дефинисан широк, али практичан скуп типова попут особа, организација и локација [19]. Формално, за реченицу представљену низом токена, задатак је пронаћи распоне (енгл. spans) који чине ентитете и сваком доделити тип [15, 21]. У основној, „равној" (енгл. flat) формулацији ентитети се не преклапају; постоји и сложенија, „угнеждена" (енгл. nested) формулација, у којој један ентитет може садржати други — на пример, у изразу „Влада Републике Србије" садржан је и назив државе [15]. У овом раду користи се равна формулација, уобичајена за примене у екстракцији информација.'));
c.push(H2('2.2. Схеме означавања'));
